import {Reports} from '../../src/features/reports.ts';import {Repository} from '../../src/domain/repository.ts';import {defaultReportSettings} from '../../src/domain/reports.ts';import type {Experiment,RecordData,Profile} from '../../src/domain/types.ts';
export async function createReportBatchFixture(){const store=new Map<string,string>(),repo=new Repository({read:async k=>store.get(k)??null,write:async(k,v)=>{store.set(k,v)},remove:async k=>{store.delete(k)}});const exp={id:'abcdef123456',name:'批量润色测试',sourceId:'批量润色测试',category:'mechanics',schema:{groups:[{name:'数据',fields:[{key:'v',label:'读数',type:'number',required:true}]}]}} as Experiment;const doc:RecordData={version:1,experimentId:exp.id,date:'2026-10-25',updatedAt:new Date().toISOString(),draft:{v:''}},profile:Profile={name:'',studentId:'',className:''};const sections={原理:'原理 $x=1$',方法:'原方法',结论:'原结论'};await repo.saveReport(exp,{version:1,experimentId:exp.id,generation:crypto.randomUUID(),createdAt:new Date().toISOString(),name:'批量润色测试',formulaCount:1,charts:[],sections,snapshot:{record:doc,profile,photoPath:null,settings:defaultReportSettings()}});await repo.saveAIPreferences(exp.id,{version:1,style:'concise',instruction:'BATCH_PREFERENCE'});let calls=0,requestText:string[]=[],failSave=false,knowledgeReads=0,missingKnowledge=false;
 const report=new Reports(repo,{context:()=>({exp,doc,profile,photo:null,blocked:false}),flush:async()=>{},notice:()=>{},jump:()=>{},confirm:async()=>true,configureAI:()=>{},upload:()=>{}},{status:async()=>({hasKey:true}),skills:async()=>[],knowledge:async sourceId=>{knowledgeReads++;if(missingKnowledge)throw Error('KNOWLEDGE_UNAVAILABLE');return {sourceId,text:'BATCH_KNOWLEDGE'}},complete:async(_slot,messages)=>{calls++;requestText.push(String(messages[0].content));if(String(messages[0].content).includes('【问答格式】'))return {text:JSON.stringify({answers:['模拟回答']}),elapsedMs:1};const content=String(messages[1].content),original=content.split('原文：')[1]??'';return {text:'已润色 '+original,elapsedMs:1};}});await report.open();return {state:()=>({calls,requestText,knowledgeReads,open:report.isOpen,saving:report.isSaving}),policy:(enabled:boolean)=>repo.saveAIKnowledgePolicy({version:1,kbOnly:enabled}),missingKnowledge:(value:boolean)=>missingKnowledge=value,settings:()=>repo.loadReportSettings(exp.id),history:()=>repo.listAIHistory(exp.id),reset:async()=>{await repo.saveReportSettings(exp.id,defaultReportSettings());report.close();await report.open();},reopen:()=>report.open()};}
